    final productProvider=context.watch<ProductProvider>();
    return Scaffold(appBar:AppBar(title:const Text('ShopEase'),actions:[IconButton(tooltip:'Refresh products',onPressed:()=>context.read<ProductProvider>().loadProducts(forceRefresh:true),icon:const Icon(Icons.refresh)),IconButton(tooltip:'Sign out',onPressed:()async{await context.read<AuthProvider>().logout();if(context.mounted)context.go('/');},icon:const Icon(Icons.logout_rounded))]),body:ListView(padding:const EdgeInsets.all(18),children:[Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xFF5B4BDB),Color(0xFF897CF0)]),borderRadius:BorderRadius.circular(22)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Hello, $name!',style:const TextStyle(color:Colors.white,fontSize:25,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('Find something you will love today.',style:TextStyle(color:Colors.white70)),const SizedBox(height:18),FilledButton.tonal(onPressed:()=>context.push('/products'),child:const Text('Explore products  →'))])),const SizedBox(height:24),Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[const Text('Shop by category',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),TextButton(onPressed:()=>context.push('/products'),child:const Text('View all'))]),Wrap(spacing:9,runSpacing:9,children:productProvider.categories.take(5).map((category)=>ActionChip(label:Text(category=='All'?'All products':category),onPressed:()=>context.push('/products'))).toList()),const SizedBox(height:24),const Text('Your shopping space',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),const SizedBox(height:10),_HomeTile(icon:Icons.storefront_outlined,title:'Product catalogue',subtitle:'Browse, search and filter products',onTap:()=>context.push('/products')),_HomeTile(icon:Icons.shopping_cart_outlined,title:'Shopping cart',subtitle:'Your cart will be available soon',onTap:()=>_soon(context)),_HomeTile(icon:Icons.favorite_border,title:'Wishlist',subtitle:'Save your favourite products',onTap:()=>_soon(context)),_HomeTile(icon:Icons.analytics_outlined,title:'Analytics dashboard',subtitle:'Your shopping statistics',onTap:()=>_soon(context)),_HomeTile(icon:Icons.person_outline,title:'My account',subtitle:auth.firebaseUser?.email??'',onTap:()=>_soon(context))]));
  }
