class _HomeTile extends StatelessWidget { const _HomeTile({required this.icon,required this.title,required this.subtitle,required this.onTap}); final IconData icon; final String title,subtitle; final VoidCallback onTap; @override Widget build(BuildContext context)=>Card(margin:const EdgeInsets.only(bottom:9),child:ListTile(leading:CircleAvatar(backgroundColor:Theme.of(context).colorScheme.primaryContainer,child:Icon(icon,color:Theme.of(context).colorScheme.primary)),title:Text(title,style:const TextStyle(fontWeight:FontWeight.w600)),subtitle:Text(subtitle),trailing:const Icon(Icons.chevron_right),onTap:onTap)); }
